Ah, right. The tokenization is done. Now I need to implement the recursive descent parser inside `evaluate`.

The structure will be:
- `parse_expression()`: handles `+` and `-` (lowest precedence). It will call `parse_term()` and loop for `+`/`-`.
- `parse_term()`: handles `*` and `/` (higher precedence). It will call `parse_factor()` and loop for `*`/`/`.
- `parse_factor()`: handles unary `+`/`-` and primary values (numbers, parenthesized expressions).

I'll use a mutable index (like a list `[0]`) to track our position in the `tokens` list across recursive calls.

```file:calc.py
import re

class ExpressionError(Exception):
    pass

def tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        if char.isspace():
            i += 1
            continue

        if char.isdigit() or char == '.':
            # Parse number
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ExpressionError(f"Invalid number format at position {j}")
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            try:
                tokens.append(float(num_str))
            except ValueError:
                raise ExpressionError(f"Invalid number '{num_str}'")
            i = j
        elif char in '+-*/()':
            tokens.append(char)
            i += 1
        else:
            raise ExpressionError(f"Unexpected character '{char}'")

    return tokens

def evaluate(expr: str) -> float:
    if not expr.strip():
        raise ExpressionError("Empty expression")

    tokens = tokenize(expr)
    pos = [0]  # Mutable index

    result, _ = parse_expression(tokens, pos)

    if pos[0] != len(tokens):
        raise ExpressionError(f"Unexpected token '{tokens[pos[0]]}' after expression")

    return result

def parse_expression(tokens, pos):
    """Handles + and -"""
    left = parse_term(tokens, pos)

    while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
        op = tokens[pos[0]]
        pos[0] += 1
        if pos[0] >= len(tokens):
            raise ExpressionError(f"Trailing operator '{op}'")
        right = parse_term(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos[0]

def parse_term(tokens, pos):
    """Handles * and /"""
    left = parse_factor(tokens, pos)

    while pos[0] < len(tokens) and tokens[pos[0]] in ('*', '/'):
        op = tokens[pos[0]]
        pos[0] += 1
        if pos[0] >= len(tokens):
            raise ExpressionError(f"Trailing operator '{op}'")
        right = parse_factor(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ExpressionError("Division by zero")
            left = left / right

    return left, pos[0]

def parse_factor(tokens, pos):
    """Handles unary +/- and primary values (numbers, parens)"""
    if pos[0] >= len(tokens):
        raise ExpressionError("Unexpected end of expression")

    token = tokens[pos[0]]

    if token == '(':
        pos[0] += 1
        value, pos[0] = parse_expression(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
            raise ExpressionError("Unbalanced parentheses")
        pos[0] += 1  # Skip ')'
        return value, pos[0]
    elif isinstance(token, float):
        pos[0] += 1
        return token, pos[0]
    elif token == '-':
        pos[0] += 1
        value, pos[0] = parse_factor(tokens, pos)
        return -value, pos[0]
    elif token == '+':
        pos[0] += 1
        value, pos[0] = parse_factor(tokens, pos)
        return value, pos[0]
    else:
        raise ExpressionError(f"Unexpected token '{token}'")
